UPDATE users
SET    reg_user = #{userNo}
WHERE  user_no  = #{userNo}

mapper.select:
SELECT user_no AS userNo -- 사용자 번호 , LOWER(user_id) AS userId -- 사용자 아이디 , user_name AS userName -- 사용자 이름 , UPPER(role) AS role -- 권한(SYSTEM/ADMIN/USER) , UPPER(status) AS status -- 계정상태(ACTIVE/DISABLED) FROM users
ORDER BY user_no DESC
LIMIT #{firstIndex}, #{recordCountPerPage}

mapper.insert:
INSERT INTO users
(
  user_id    -- 사용자 아이디 (소문자 저장)
, user_pw    -- 비밀번호
, user_name  -- 이름
, role       -- 권한
, status     -- 계정상태
, reg_date   -- 최초등록일시
, reg_user   -- 최초등록자 (로그인 사용자 userNo)
)
VALUES
(
  LOWER(#{userId})
, #{userPw}
, #{userName}
, #{role}
, #{status}
, NOW()
, #{regUser}
)

mapper.update:
UPDATE users SET user_name = #{userName} -- 이름 , role = #{role} -- 권한 , status = #{status} -- 계정상태 , mod_date = NOW() -- 수정일시 (자동) , mod_user = #{modUser} -- 수정자 (로그인 사용자 userNo)
, user_pw = #{userPw} -- 비밀번호 (입력된 경우에만 변경)
WHERE user_no = #{userNo}

UPDATE users
SET
      status   = 'DISABLED'    
    , mod_date = NOW()         
    , mod_user = #{modUser}    
WHERE  user_no = #{userNo}
